create table if not exists public.medicine_types (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,name text not null,status boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,name),unique(business_id,id));
create table if not exists public.manufacturers (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,name text not null,description text,status boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,name),unique(business_id,id));
alter table public.products add constraint products_type_business_fk foreign key (business_id,type_id) references public.medicine_types(business_id,id) on delete set null;
alter table public.products add constraint products_manufacturer_business_fk foreign key (business_id,manufacturer_id) references public.manufacturers(business_id,id) on delete set null;
do $$ declare t text; begin for t in select unnest(array['medicine_types','manufacturers']) loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on table public.%I to authenticated',t); execute format('create policy %I on public.%I for all to authenticated using (business_id=(select public.current_business_id())) with check (business_id=(select public.current_business_id()))',t||'_tenant_policy',t); end loop; end $$;